namespace ghidra.feature.vt.gui.actions;



using docking;
using docking.action;
using generic.theme;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.functionassociation;
using ghidra.util;

/**
 * Action that selects the function match, if it exists, for the currently selected source and 
 * destination functions in the tables.
 */
public class SelectExistingMatchAction : DockingAction {

	private static readonly Icon ICON =
		new GIcon("icon.version.tracking.action.match.select.existing");

	private static readonly string MENU_GROUP = "Create";

	private VTController controller;

	/**
	 * Constructor for the action.
	 * @param controller the controller for the current version tracking session.
	 */
	public SelectExistingMatchAction(VTController controller) : base("Select Exising Match", VTPlugin.OWNER)
    {
		this.controller = controller;

		setToolBarData(new ToolBarData(ICON, MENU_GROUP));
		setPopupMenuData(new MenuData(new string[] { "Select Existing Match" }, ICON));
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Select_Existing_Match"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		FunctionAssociationContext providerContext = (FunctionAssociationContext) context;
		VTMatch match = providerContext.getExistingMatch();
		controller.setSelectedMatch(match);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is FunctionAssociationContext)) {
			return false;
		}

		FunctionAssociationContext providerContext = (FunctionAssociationContext) context;
		return providerContext.getExistingMatch() != null;
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return (context is FunctionAssociationContext);
	}
}
